//! The drift controller: decides how fast to consume audio.
//!
//! ## The signal, and why it is this one
//!
//! Buffer depth — frames waiting to be played — measured by the render
//! callback. Two more obvious candidates are both wrong:
//!
//! * **`timestampUs` from the packet headers** carries no drift information at
//!   all. It is generated by the sender from its own frame count, so it says
//!   what the sender thinks, not how the two clocks relate.
//! * **`CLOCK_MONOTONIC`** is a different clock from the audio PLL. On many
//!   devices it is derived from a separate oscillator, so comparing arrival
//!   times against it measures the drift between the system clock and the
//!   sender, which is not the drift that empties the buffer.
//!
//! The depth trend is the only signal that is affected by exactly the two
//! clocks that matter, because it rises when input outpaces output and falls
//! when output outpaces input, by definition.
//!
//! ## Why a PI controller rather than a threshold
//!
//! A proportional-only controller leaves a standing error: it needs a depth
//! offset to generate the correction that a constant clock difference
//! requires, so the buffer would sit permanently off target and have less
//! headroom on one side than the other. The integral term removes that — it
//! learns the clock difference and holds it without needing an error to
//! sustain it.
//!
//! A threshold ("if too full, drop a packet") is the alternative this replaces:
//! it costs an audible discontinuity every couple of minutes, where this costs
//! a pitch shift nobody can hear.

use crate::resample::{MAX_BURST_PPM, MAX_STEADY_PPM};

/// How the controller is tuned.
#[derive(Debug, Clone, Copy)]
pub struct DriftConfig {
    pub sample_rate: u32,
    /// Depth the controller steers towards, in frames.
    pub target_frames: usize,
    /// Roughly how long a depth error takes to be corrected.
    ///
    /// 15 s is slow enough that normal jitter does not move the correction and
    /// fast enough to retire a real error long before the buffer runs out.
    pub settle_seconds: f64,
    /// Smoothing applied to the depth measurement.
    ///
    /// Depth swings by whole packets as they arrive, so the raw measurement is
    /// far noisier than the drift it is being used to estimate. 2 s of
    /// averaging separates the two.
    pub filter_seconds: f64,
    /// How long the burst clamp may be used before dropping back to steady.
    pub burst_budget_seconds: f64,
    /// Excess depth that resampling should not attempt to retire, in frames.
    ///
    /// Resampling is bounded by the steady clamp: 500 ppm drains 24 frames a
    /// second at 48 kHz, so 200 ms of backlog would take **seven minutes** to
    /// retire — seven minutes during which the performer hears everything
    /// 200 ms late. Latency is the product, so beyond this threshold the
    /// caller should skip forward with a fade instead, paying one soft
    /// discontinuity to get the latency back immediately.
    ///
    /// The default is 40 ms, which is more than an entire buffer at the Normal
    /// preset: being that far over target means an outage happened, not that
    /// two crystals disagree.
    pub skip_above_frames: usize,
}

impl DriftConfig {
    /// The reviewed defaults.
    #[must_use]
    pub const fn new(sample_rate: u32, target_frames: usize) -> Self {
        Self {
            sample_rate,
            target_frames,
            settle_seconds: 15.0,
            filter_seconds: 2.0,
            burst_budget_seconds: 5.0,
            // 40 ms.
            skip_above_frames: (sample_rate as usize) * 40 / 1_000,
        }
    }
}

/// Drives the resampler's correction from the buffer depth trend.
#[derive(Debug, Clone)]
pub struct DriftController {
    config: DriftConfig,
    /// Smoothed depth error, in frames.
    filtered_error: f64,
    /// Has the filter seen anything yet?
    primed: bool,
    /// Learned clock difference, in ppm.
    integral_ppm: f64,
    /// Burst allowance consumed, in seconds.
    burst_used: f64,
    /// Seconds of measurement since the last resync.
    observed: f64,
    /// Slow average of the applied correction: the reported clock estimate.
    smoothed_ppm: f64,
    correction_ppm: f64,
    /// Proportional gain, ppm per frame of error.
    kp: f64,
    /// Integral gain, ppm per frame-second of error.
    ki: f64,
}

impl DriftController {
    #[must_use]
    pub fn new(config: DriftConfig) -> Self {
        // To make a depth error decay with time constant `settle`, the drain
        // rate must be error/settle frames per second. The resampler drains at
        // ppm * 1e-6 * sample_rate frames per second, so:
        //
        //     ppm = error * 1e6 / (settle * sample_rate)
        let kp = 1e6 / (config.settle_seconds * f64::from(config.sample_rate.max(1)));

        // The integral gain sets the damping, and the loop is fussier about it
        // than it looks. Buffer depth *integrates* the rate error, so the
        // plant is 1/s and a PI controller around it is second order:
        //
        //     ë + K·kp·ė + K·ki·e = 0,  K = sample_rate × 1e-6
        //
        // giving ωn = √(K·ki) and ζ = K·kp / (2·ωn). At kp/30 that is
        // ζ ≈ 0.71 — textbook-optimal for a step response, and wrong here.
        // The depth measurement carries an unavoidable one-packet sawtooth
        // (the sender adds 240 frames at a time while the resampler drains
        // continuously), which excites the loop continuously; a loop with any
        // ringing left in it then hunts, and the figure a receiver reports
        // about its own clock drift wanders by tens of ppm. Measured over 40
        // simulated minutes, kp/30 left the integral swinging between +68 and
        // −4 ppm against a true 40.
        //
        // kp/120 gives ζ ≈ 1.4: overdamped, no ringing, dominant time
        // constant about two minutes. Two minutes is nothing against a drift
        // that takes 90 to matter, and the reported figure stops lying.
        let ki = kp / 120.0;

        Self {
            config,
            filtered_error: 0.0,
            primed: false,
            integral_ppm: 0.0,
            burst_used: 0.0,
            observed: 0.0,
            smoothed_ppm: 0.0,
            correction_ppm: 0.0,
            kp,
            ki,
        }
    }

    /// Changes the depth the controller steers towards.
    ///
    /// Called when the jitter-buffer adaptation raises or lowers its target.
    /// The integral is kept: the clock difference it has learned is still true,
    /// and discarding it would make every target change re-learn it over the
    /// following minute.
    pub fn set_target_frames(&mut self, frames: usize) {
        self.config.target_frames = frames;
    }

    #[must_use]
    pub const fn target_frames(&self) -> usize {
        self.config.target_frames
    }

    /// Updates from a depth measurement. Returns the correction in ppm.
    ///
    /// `depth_frames` counts every slot from the read position to the newest
    /// packet, holes included — see `JitterBuffer::span_from`. Holes belong in
    /// the figure because the reader conceals them and moves on, so each one
    /// still takes a packet interval to play; counting only gap-free audio
    /// would report a near-empty buffer on a lossy stream and have the
    /// controller correct a deficit that is not there.
    pub fn update(&mut self, depth_frames: usize, dt_seconds: f64) -> f64 {
        if !dt_seconds.is_finite() || dt_seconds <= 0.0 {
            return self.correction_ppm;
        }

        self.observed += dt_seconds;
        let error = depth_frames as f64 - self.config.target_frames as f64;

        // One-pole smoothing, seeded on the first call so the controller does
        // not spend its first two seconds believing the buffer is at target.
        if self.primed {
            let alpha = 1.0 - (-dt_seconds / self.config.filter_seconds.max(1e-3)).exp();
            self.filtered_error += (error - self.filtered_error) * alpha;
        } else {
            self.filtered_error = error;
            self.primed = true;
        }

        let proportional = self.filtered_error * self.kp;

        // Integrate, with the integral itself clamped rather than the sum.
        // Clamping only the output would let the integral wind up to an
        // enormous value during an outage and then take minutes to unwind,
        // holding the pitch shifted the whole time.
        self.integral_ppm += self.filtered_error * self.ki * dt_seconds;
        self.integral_ppm = self.integral_ppm.clamp(-MAX_STEADY_PPM, MAX_STEADY_PPM);

        let requested = proportional + self.integral_ppm;

        // Steady state is capped well below audibility. More is allowed only
        // briefly, to retire the backlog an outage left behind.
        let limit = if self.burst_used < self.config.burst_budget_seconds {
            MAX_BURST_PPM
        } else {
            MAX_STEADY_PPM
        };
        self.correction_ppm = requested.clamp(-limit, limit);

        // Two minutes of averaging, matching the loop's own dominant time
        // constant. Shorter than that and the reported figure tracks the
        // controller's own motion rather than the clocks: the depth wanders
        // a few milliseconds over minutes, and the proportional term turns
        // each millisecond into tens of ppm.
        let smoothing = 1.0 - (-dt_seconds / 120.0).exp();
        self.smoothed_ppm += (self.correction_ppm - self.smoothed_ppm) * smoothing;

        if self.correction_ppm.abs() > MAX_STEADY_PPM {
            self.burst_used += dt_seconds;
        } else {
            // Recovers at a tenth of real time, so bursts cannot be chained
            // into a sustained pitch shift.
            self.burst_used = (self.burst_used - dt_seconds / 10.0).max(0.0);
        }

        self.correction_ppm
    }

    #[must_use]
    pub const fn correction_ppm(&self) -> f64 {
        self.correction_ppm
    }

    /// Whether this depth is too far over target for resampling to fix.
    ///
    /// The caller skips forward with a fade when this is true. Resampling that
    /// much backlog away would hold the extra latency for minutes, and latency
    /// is the whole point of the system.
    ///
    /// Uses the **smoothed** error rather than the instantaneous depth, and
    /// refuses to answer until the filter has had a full window of
    /// measurements. Both matter: a skip is audible, and the depth immediately
    /// after a stream starts is whatever happened to have arrived during
    /// priming, which is not yet evidence of a backlog. Acting on it would
    /// make every session begin with a skip.
    #[must_use]
    pub fn excess_needs_skip(&self) -> bool {
        self.primed
            && self.observed >= self.config.filter_seconds
            && self.filtered_error > self.config.skip_above_frames as f64
    }

    /// Frames to discard to put the depth back on target.
    #[must_use]
    pub fn skip_frames(&self) -> usize {
        self.filtered_error.max(0.0) as usize
    }

    /// The clock difference this receiver has settled on, in ppm.
    ///
    /// A two-minute average of the correction actually applied — **not** the
    /// integral term. The integral is only one contributor; in a well-behaved
    /// loop the proportional term carries most of a steady rate difference
    /// against a small standing error, so the integral alone is not the
    /// clock estimate and reporting it as one is misleading. The applied rate
    /// is what the resampler really ran at, and averaging it over the loop's
    /// own time constant removes the proportional term's response to
    /// ordinary depth variation.
    ///
    /// Worth reporting: a value pinned near the clamp for minutes means the
    /// two clocks are further apart than the budget allows, and that is the
    /// one symptom which shows up before a dropout does.
    #[must_use]
    pub const fn learned_ppm(&self) -> f64 {
        self.smoothed_ppm
    }

    /// The integral term alone, for tests that need to see inside the loop.
    #[must_use]
    pub const fn integral_ppm(&self) -> f64 {
        self.integral_ppm
    }

    #[must_use]
    pub fn filtered_error_frames(&self) -> f64 {
        self.filtered_error
    }

    /// Forgets the depth error but keeps the learned clock difference.
    ///
    /// Called on a resync. The buffer's contents are gone, so the error is
    /// meaningless, but the crystals have not changed.
    pub fn resync(&mut self) {
        self.filtered_error = 0.0;
        self.primed = false;
        self.observed = 0.0;
        self.correction_ppm = self.integral_ppm;
    }

    /// Forgets everything, including the learned clock difference. For a new
    /// session against a possibly different sender.
    pub fn reset(&mut self) {
        self.filtered_error = 0.0;
        self.primed = false;
        self.integral_ppm = 0.0;
        self.burst_used = 0.0;
        self.observed = 0.0;
        self.smoothed_ppm = 0.0;
        self.correction_ppm = 0.0;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const RATE: u32 = 48_000;
    const TARGET: usize = 1_920; // 40 ms

    fn controller() -> DriftController {
        DriftController::new(DriftConfig::new(RATE, TARGET))
    }

    /// Closed-loop simulation.
    ///
    /// The plant: input arrives at `sender_ppm` relative to nominal, output is
    /// consumed at the correction the controller asks for. Depth therefore
    /// changes by `sample_rate * (sender_ppm - correction) * 1e-6` frames per
    /// second — which is the whole physical situation, in one line.
    ///
    /// Returns the depth history, sampled per step.
    fn simulate(
        controller: &mut DriftController,
        sender_ppm: f64,
        initial_depth: f64,
        seconds: f64,
    ) -> Vec<f64> {
        const DT: f64 = 0.005; // one packet
        let mut depth = initial_depth;
        let mut history = Vec::new();

        for _ in 0..(seconds / DT) as usize {
            let correction = controller.update(depth.max(0.0) as usize, DT);
            let rate = f64::from(RATE) * (sender_ppm - correction) / 1e6;
            depth += rate * DT;
            history.push(depth);
        }
        history
    }

    #[test]
    fn at_target_with_matched_clocks_it_asks_for_nothing() {
        let mut controller = controller();
        let history = simulate(&mut controller, 0.0, TARGET as f64, 30.0);
        assert!(
            (history.last().unwrap() - TARGET as f64).abs() < 1.0,
            "the depth wandered to {}",
            history.last().unwrap()
        );
        assert!(
            controller.correction_ppm().abs() < 1.0,
            "it asked for {} ppm with nothing to correct",
            controller.correction_ppm()
        );
    }

    /// The case the module exists for. A 40 ppm sender would accumulate 216 ms
    /// over a 90-minute service; the controller has to hold the depth steady
    /// instead.
    #[test]
    fn a_forty_ppm_sender_is_tracked_and_the_depth_holds() {
        let mut controller = controller();
        let history = simulate(&mut controller, 40.0, TARGET as f64, 300.0);

        // It learns the sender's rate, not merely a rate.
        assert!(
            (controller.learned_ppm() - 40.0).abs() < 4.0,
            "learned {} ppm, expected 40",
            controller.learned_ppm()
        );

        // And the depth is back on target rather than parked off it, which is
        // what a proportional-only controller would do.
        let settled = history.last().unwrap();
        assert!(
            (settled - TARGET as f64).abs() < 48.0,
            "settled {} frames from target",
            settled - TARGET as f64
        );

        // Over five minutes, uncorrected 40 ppm would have drained 576 frames.
        let worst = history
            .iter()
            .map(|&depth| (depth - TARGET as f64).abs())
            .fold(0.0_f64, f64::max);
        assert!(worst < 200.0, "the depth deviated by {worst} frames");
    }

    #[test]
    fn it_corrects_in_both_directions() {
        for sender_ppm in [-100.0, -40.0, 40.0, 100.0] {
            let mut controller = controller();
            simulate(&mut controller, sender_ppm, TARGET as f64, 300.0);
            assert!(
                (controller.learned_ppm() - sender_ppm).abs() < 10.0,
                "sender at {sender_ppm} ppm, learned {}",
                controller.learned_ppm()
            );
        }
    }

    /// A small excess is retired by resampling, inaudibly.
    #[test]
    fn a_slightly_full_buffer_is_drained_by_resampling_alone() {
        let mut controller = controller();
        // 10 ms over: well within what the clamp can retire.
        let history = simulate(&mut controller, 0.0, (TARGET + 480) as f64, 120.0);

        let over = history.last().unwrap() - TARGET as f64;
        assert!(over.abs() < 48.0, "still {over} frames off target after two minutes");
        assert!(
            !controller.excess_needs_skip(),
            "10 ms should not warrant an audible skip"
        );
    }

    /// An outage leaves the buffer far too full once packets resume, and
    /// resampling cannot fix it: at the 500 ppm steady clamp, 200 ms of
    /// backlog takes seven minutes to drain, and the performer hears
    /// everything 200 ms late for all of it. The controller must say so rather
    /// than quietly trying.
    #[test]
    fn a_badly_full_buffer_asks_for_a_skip_instead_of_resampling_for_minutes() {
        let mut controller = controller();
        // 200 ms too full, as an outage leaves it. Five seconds is long enough
        // for the 2 s filter to believe the measurement.
        simulate(&mut controller, 0.0, (TARGET + 9_600) as f64, 5.0);

        assert!(
            controller.excess_needs_skip(),
            "200 ms of backlog was not reported as needing a skip"
        );
        // And it says how much to discard, so the caller lands on target
        // rather than guessing.
        let skip = controller.skip_frames();
        assert!(
            (7_000..=9_600).contains(&skip),
            "asked to skip {skip} frames for a 9600-frame excess"
        );

        // The sustained correction stays inside the steady limit: the burst
        // allowance is for retiring the last of a backlog, not for holding a
        // 3.5-cent pitch shift for the rest of the service.
        simulate(&mut controller, 0.0, (TARGET + 9_600) as f64, 120.0);
        assert!(
            controller.correction_ppm().abs() <= MAX_STEADY_PPM,
            "sustained correction of {} ppm",
            controller.correction_ppm()
        );
    }

    #[test]
    fn an_empty_buffer_never_asks_for_a_skip() {
        // There is nothing to skip towards: concealment and refilling are the
        // only answers, and asking for a backwards skip would be nonsense.
        let mut controller = controller();
        simulate(&mut controller, 0.0, 0.0, 10.0);
        assert!(!controller.excess_needs_skip());
        assert_eq!(controller.skip_frames(), 0);
    }

    #[test]
    fn a_near_empty_buffer_is_refilled_without_exceeding_the_burst_limit() {
        let mut controller = controller();
        let history = simulate(&mut controller, 0.0, 48.0, 60.0);

        assert!(
            *history.last().unwrap() > (TARGET - 480) as f64,
            "the buffer was not refilled: {}",
            history.last().unwrap()
        );
        // Never beyond the hard burst limit, in either direction.
        assert!(controller.correction_ppm().abs() <= MAX_BURST_PPM);
        // And it refilled by slowing down, not by any other means.
        assert!(controller.correction_ppm() < 0.0 || controller.learned_ppm() < 0.0);
    }

    #[test]
    fn the_correction_never_exceeds_the_burst_limit_however_wrong_the_depth() {
        let mut controller = controller();
        for depth in [0_usize, 1, 100_000, usize::MAX / 2] {
            let correction = controller.update(depth, 0.005);
            assert!(
                correction.abs() <= MAX_BURST_PPM,
                "depth {depth} produced {correction} ppm"
            );
            assert!(correction.is_finite());
        }
    }

    #[test]
    fn a_sustained_error_settles_inside_the_steady_limit() {
        let mut controller = controller();
        // Hold the depth wildly over target forever: the burst budget must run
        // out and the correction fall back, rather than holding 2000 ppm — a
        // 3.5-cent pitch shift — for the rest of the service.
        for _ in 0..20_000 {
            controller.update(TARGET + 50_000, 0.005);
        }
        assert!(
            controller.correction_ppm() <= MAX_STEADY_PPM,
            "held {} ppm indefinitely",
            controller.correction_ppm()
        );
    }

    #[test]
    fn the_integral_cannot_wind_up_during_an_outage() {
        let mut controller = controller();
        // Twenty seconds of an empty buffer, as a dead network looks.
        for _ in 0..4_000 {
            controller.update(0, 0.005);
        }
        assert!(
            controller.learned_ppm() >= -MAX_STEADY_PPM,
            "the integral wound up to {} ppm",
            controller.learned_ppm()
        );

        // And once packets resume at the target depth, the correction comes
        // back near zero in tens of seconds rather than minutes.
        let history = simulate(&mut controller, 0.0, TARGET as f64, 120.0);
        assert!(
            (history.last().unwrap() - TARGET as f64).abs() < 240.0,
            "recovery left the depth {} frames off",
            history.last().unwrap() - TARGET as f64
        );
    }

    #[test]
    fn a_resync_forgets_the_depth_but_not_the_clocks() {
        let mut controller = controller();
        simulate(&mut controller, 40.0, TARGET as f64, 300.0);
        let learned = controller.learned_ppm();
        assert!(learned > 30.0);

        let integral = controller.integral_ppm();
        controller.resync();
        assert_eq!(controller.filtered_error_frames(), 0.0);
        assert!(
            (controller.learned_ppm() - learned).abs() < 1e-9,
            "a resync must not discard what was learned about the crystals"
        );
        assert!(
            (controller.integral_ppm() - integral).abs() < 1e-9,
            "nor the integral that is holding the rate"
        );
        // The correction falls back to the integral: the depth error it was
        // also responding to is gone, but the clock difference is not.
        assert!((controller.correction_ppm() - integral).abs() < 1e-9);
    }

    #[test]
    fn a_reset_forgets_everything() {
        let mut controller = controller();
        simulate(&mut controller, 40.0, TARGET as f64, 300.0);
        controller.reset();
        assert_eq!(controller.learned_ppm(), 0.0);
        assert_eq!(controller.correction_ppm(), 0.0);
    }

    #[test]
    fn a_new_target_is_steered_to_without_relearning_the_clocks() {
        let mut controller = controller();
        simulate(&mut controller, 40.0, TARGET as f64, 600.0);
        let integral = controller.integral_ppm();

        // The jitter-buffer adaptation raises the target by 40 ms.
        controller.set_target_frames(TARGET + 1_920);
        let history = simulate(&mut controller, 40.0, TARGET as f64, 600.0);

        assert!(
            (history.last().unwrap() - (TARGET + 1_920) as f64).abs() < 240.0,
            "did not reach the new target: {}",
            history.last().unwrap()
        );
        // The integral is what holds the learned rate, and a target change
        // must not make it relearn the crystals from scratch. The correction
        // itself legitimately swings while the loop re-steers.
        assert!(
            (controller.integral_ppm() - integral).abs() < 40.0,
            "a target change threw away the clock estimate: {integral:.1} -> {:.1}",
            controller.integral_ppm()
        );
    }

    #[test]
    fn a_nonsense_timestep_is_ignored_rather_than_poisoning_the_loop() {
        let mut controller = controller();
        controller.update(TARGET + 480, 0.005);
        let before = controller.correction_ppm();

        for dt in [0.0, -1.0, f64::NAN, f64::INFINITY] {
            let correction = controller.update(TARGET + 480, dt);
            assert_eq!(correction, before, "dt {dt} changed the correction");
        }
        assert!(controller.learned_ppm().is_finite());
    }
}

